import sys
from collections import deque

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        T = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(T):
        try:
            N = int(next(iterator))
            A_str = next(iterator)
            B_str = next(iterator)
        except StopIteration:
            break

        A_list = sorted(list(A_str))
        B_list = sorted(list(B_str))

        a_deque = deque(A_list)
        b_deque = deque(B_list)

        S = [''] * (2 * N)
        left = 0
        right = 2 * N - 1

        turn = 0

        while left <= right:
            if turn % 2 == 0:
                char = a_deque.popleft()
                if left < right:
                    if char > b_deque[0]:
                        S[right] = char
                        right -= 1
                    else:
                        S[left] = char
                        left += 1
                else:
                    S[left] = char
                    left += 1
            else:
                char = b_deque.popleft()
                if left < right:
                    if b_deque[0] > char:
                        S[left] = char
                        left += 1
                    else:
                        S[right] = char
                        right -= 1
                else:
                    S[left] = char
                    right -= 1

            turn += 1

        results.append("".join(S))

    print("\n".join(results))

if __name__ == "__main__":
    solve()
